 void hideKeyboard(){View v=getCurrentFocus();if(v!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);root.clearFocus();}
 ArrayList<String> allCategories(){LinkedHashSet<String> names=new LinkedHashSet<>(Arrays.asList(cats));names.remove(CategoryCatalog.OTHER);names.addAll(new TreeSet<>(getSharedPreferences("library-ui",MODE_PRIVATE).getStringSet("custom-categories",Collections.emptySet())));for(JSONObject d:docs){String name=d.optString("category");if(!name.isEmpty()&&!CategoryCatalog.OTHER.equals(name))names.add(name);}names.add(CategoryCatalog.OTHER);return new ArrayList<>(names);}
 void chooseCategory(String selected,boolean includeAll,java.util.function.Consumer<String> onPick){
  hideKeyboard();ArrayList<String> names=allCategories();if(includeAll)names.add(0,CategoryCatalog.ALL);
  LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),dp(8));EditText search=new EditText(this);search.setSingleLine(true);search.setHint("ค้นหาหมวด เช่น มะเร็ง / ไต / เด็ก");fieldStyle(search);form.addView(search);gap(form,8);
  ListView choices=new ListView(this);choices.setDivider(null);choices.setChoiceMode(ListView.CHOICE_MODE_SINGLE);choices.setPadding(0,0,0,0);
  ArrayList<String> shown=new ArrayList<>(names);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_single_choice,shown);choices.setAdapter(adapter);choices.setItemChecked(shown.indexOf(selected),true);
  form.addView(choices,new LinearLayout.LayoutParams(-1,dp(Math.min(340,(int)(getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density*.42)))));
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("เลือกหมวดหมู่โรค").setView(form).setNegativeButton("ปิด",null).setNeutralButton("＋ เพิ่มหมวดเอง",null).create();
  choices.setOnItemClickListener((parent,v,pos,id)->{onPick.accept(shown.get(pos));dialog.dismiss();});
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int a,int c,int f){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence x,int a,int before,int count){shown.clear();String q=x.toString().trim().toLowerCase(Locale.ROOT);for(String name:names)if(name.toLowerCase(Locale.ROOT).contains(q))shown.add(name);adapter.notifyDataSetChanged();choices.clearChoices();choices.setItemChecked(shown.indexOf(selected),true);}});
  dialog.setOnShowListener(x->{dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getButton(-3).setOnClickListener(v->{EditText input=new EditText(this);input.setHint("ชื่อหมวดใหม่");input.setSingleLine(true);fieldStyle(input);LinearLayout add=column();add.setPadding(dp(20),dp(12),dp(20),0);add.addView(input);AlertDialog custom=new AlertDialog.Builder(this).setTitle("เพิ่มหมวดของฉัน").setView(add).setNegativeButton("ยกเลิก",null).setPositiveButton("เพิ่ม",null).create();custom.setOnShowListener(z->custom.getButton(-1).setOnClickListener(b->{String value=input.getText().toString().trim();if(value.isEmpty()||value.length()>80||CategoryCatalog.ALL.equals(value)){input.setError("ระบุชื่อหมวด 1–80 ตัวอักษร");return;}Set<String> saved=new HashSet<>(getSharedPreferences("library-ui",MODE_PRIVATE).getStringSet("custom-categories",Collections.emptySet()));saved.add(value);getSharedPreferences("library-ui",MODE_PRIVATE).edit().putStringSet("custom-categories",saved).apply();onPick.accept(value);custom.dismiss();dialog.dismiss();}));custom.show();});});dialog.show();
 }

 void base(){root=column();root.setPadding(dp(20),dp(12),dp(20),dp(8));root.setBackgroundColor(BG);root.setFocusableInTouchMode(true);setContentView(root);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void home(){
  closePdf();active=null;base();
  LinearLayout heading=row();heading.addView(brandIcon(38));LinearLayout brand=column();brand.setPadding(dp(10),0,0,0);TextView name=text("pharmnote.",23,GREEN);name.setTypeface(null,1);name.setPadding(0,0,0,0);brand.addView(name);TextView tagline=text("พื้นที่การเรียนรู้ของคุณ",11,0xFF879681);tagline.setPadding(0,0,0,0);brand.addView(tagline);heading.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button more=button("⋮",this::menu);more.setContentDescription("เมนูแอปและอัปเดต");more.setTextSize(22);heading.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(heading);gap(root,18);
  TextView title=text("คลัง Guideline ของฉัน",25,INK);title.setTypeface(null,1);root.addView(title);
  Set<String> used=new HashSet<>();for(JSONObject d:docs)used.add(d.optString("category"));
  TextView subtitle=text(docs.isEmpty()?"รวมความรู้ทุกหน้า เพื่อการดูแลที่ดีขึ้น":docs.size()+" เอกสาร  ·  "+used.size()+" หมวดที่กำลังเรียนรู้",13,0xFF81917E);root.addView(subtitle);gap(root,12);
  LinearLayout searchRow=row();EditText search=new EditText(this);search.setSingleLine(true);search.setHint("ค้นหาโรค / guideline / องค์กร");fieldStyle(search);search.setText(query);searchRow.addView(search,new LinearLayout.LayoutParams(0,dp(50),1));Button upload=primary("＋ PDF",this::pickPdf);upload.setContentDescription("เพิ่ม Guideline PDF");LinearLayout.LayoutParams up=new LinearLayout.LayoutParams(-2,dp(50));up.setMargins(dp(8),0,0,0);searchRow.addView(upload,up);root.addView(searchRow);gap(root,10);
  Button category=button((CategoryCatalog.ALL.equals(filter)?"ทุกหมวดหมู่โรค":filter)+"  ▾",()->chooseCategory(filter,true,value->{filter=value;home();}));category.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);root.addView(category,new LinearLayout.LayoutParams(-1,dp(48)));gap(root,10);
  int favCount=0;for(JSONObject d:docs)if(d.optBoolean("favorite"))favCount++;
  LinearLayout tabs=row();Button all=favorites?button("ทั้งหมด  "+docs.size(),()->{favorites=false;home();}):primary("ทั้งหมด  "+docs.size(),()->{});Button fav=favorites?primary("★ โปรด  "+favCount,()->{}):button("☆ โปรด  "+favCount,()->{favorites=true;home();});tabs.addView(all,new LinearLayout.LayoutParams(0,dp(46),1));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(0,dp(46),1);fp.setMargins(dp(8),0,0,0);tabs.addView(fav,fp);root.addView(tabs);gap(root,4);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);list=column();list.setPadding(0,0,0,dp(12));scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  TextView privacy=text("เก็บไว้ในเครื่องคุณ  ·  อ่านและทบทวนแบบออฟไลน์ได้",10,0xFF93A08D);privacy.setGravity(Gravity.CENTER);root.addView(privacy);
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int a,int c,int f){}public void onTextChanged(CharSequence x,int a,int before,int count){query=x.toString();render();}public void afterTextChanged(Editable e){}});render();
 }
 void menu(){new AlertDialog.Builder(this).setTitle("Pharmnote "+BuildConfig.VERSION_NAME).setItems(new String[]{"ตรวจสอบอัปเดต","ตั้งค่าแหล่งอัปเดต GitHub","ส่งออกข้อมูลสำรอง"},(d,which)->{if(which==0)UpdateChecker.check(this,true);if(which==1)UpdateChecker.configure(this);if(which==2)exportBackup();}).show();}
 void render(){
  list.removeAllViews();int count=0;
  for(JSONObject d:docs){
   String hay=(d.optString("title")+" "+d.optString("org")+" "+d.optString("category")+" "+d.optString("year")).toLowerCase(Locale.ROOT);
   if(!hay.contains(query.toLowerCase(Locale.ROOT))||(!CategoryCatalog.ALL.equals(filter)&&!filter.equals(d.optString("category")))||(favorites&&!d.optBoolean("favorite")))continue;
   count++;LinearLayout card=column();card.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable surface=shape(Color.WHITE);surface.setCornerRadius(dp(18));surface.setStroke(dp(1),0xFFE2E9DE);card.setBackground(surface);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(12),0,0);list.addView(card,cp);
   LinearLayout top=row();TextView pdf=pill("PDF");pdf.setTypeface(null,1);top.addView(pdf);TextView cat=text(d.optString("category"),12,0xFF7C9071);cat.setPadding(dp(10),0,dp(4),0);top.addView(cat,new LinearLayout.LayoutParams(0,-2,1));Button star=button(d.optBoolean("favorite")?"★":"☆",()->{boolean old=d.optBoolean("favorite");try{d.put("favorite",!old);if(!persist())d.put("favorite",old);render();}catch(Exception ignored){}});star.setTextSize(22);star.setContentDescription(d.optBoolean("favorite")?"นำออกจากรายการโปรด":"เพิ่มในรายการโปรด");top.addView(star,new LinearLayout.LayoutParams(dp(48),dp(48)));card.addView(top);
   TextView title=text(d.optString("title"),19,INK);title.setTypeface(null,1);card.addView(title);String meta=d.optString("org");if(!d.optString("year").isEmpty())meta+=(meta.isEmpty()?"":"  ·  ")+d.optString("year");if(!meta.isEmpty())card.addView(text(meta,12,0xFF899681));
   JSONObject notes=d.optJSONObject("notes");int notesCount=0;if(notes!=null)for(String type:new String[]{"explain","regimen"}){JSONObject n=notes.optJSONObject(type);if(n!=null&&!n.optString("answer").trim().isEmpty())notesCount++;}
   card.addView(text(notesCount>0?"มีสรุปแล้ว "+notesCount+" ชุด":"พร้อมอ่านและสร้างสรุปของคุณ",11,0xFF8D9C83));gap(card,9);
   LinearLayout actions=row();actions.addView(primary("เปิดอ่าน  ↗",()->open(d,0)),new LinearLayout.LayoutParams(0,dp(48),1));Button edit=button("ข้อมูล",()->editMetadata(d));edit.setContentDescription("แก้ชื่อ หมวด องค์กร และปีของเอกสาร");LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-2,dp(48));ep.setMargins(dp(8),0,0,0);actions.addView(edit,ep);card.addView(actions);
  }
  if(count==0){LinearLayout empty=column();empty.setGravity(Gravity.CENTER_HORIZONTAL);empty.setPadding(dp(22),dp(28),dp(22),dp(26));GradientDrawable surface=shape(0xFFEDF3E5);surface.setCornerRadius(dp(22));empty.setBackground(surface);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,-2);ep.setMargins(0,dp(16),0,0);list.addView(empty,ep);empty.addView(brandIcon(64));gap(empty,15);TextView t=text(docs.isEmpty()?"เริ่มคลังความรู้ของคุณ":favorites?"ยังไม่มีรายการโปรดที่ตรงกัน":"ยังไม่พบเอกสารที่ค้นหา",20,GREEN);t.setGravity(Gravity.CENTER);t.setTypeface(null,1);empty.addView(t);TextView hint=text(docs.isEmpty()?"เพิ่ม guideline ฉบับแรก แล้วเก็บคำอธิบาย\nและสรุป regimen ไว้ทบทวนด้วยกัน":"ลองเปลี่ยนคำค้นหรือหมวดหมู่\nหรือเพิ่ม PDF ที่อยากเรียนรู้",14,0xFF829176);hint.setGravity(Gravity.CENTER);hint.setLineSpacing(dp(3),1f);empty.addView(hint);gap(empty,16);empty.addView(primary("＋ เพิ่ม Guideline PDF",this::pickPdf));}
 }
 void pickPdf(){if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(request==1)importPdf(data.getData());if(request==2)writeBackup(data.getData());}
 void importPdf(Uri uri){busy=true;toast("กำลังนำเข้า PDF…");new Thread(()->{String id=UUID.randomUUID().toString();File file=new File(getFilesDir(),id+".pdf");try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException();byte[] buf=new byte[8192];int n;long total=0;while((n=in.read(buf))!=-1){total+=n;if(total>50L*1024*1024)throw new IOException("ใหญ่เกิน 50 MB");out.write(buf,0,n);}}try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd)){if(pdf.getPageCount()<1)throw new IOException();}runOnUiThread(()->{busy=false;metadata(id,file);});}catch(Exception e){file.delete();runOnUiThread(()->{busy=false;toast("นำเข้าไม่ได้: PDF อาจเสียหาย มีรหัสผ่าน หรือใหญ่เกิน 50 MB");});}}).start();}
 EditText field(LinearLayout parent,String label,String value,boolean multiline){gap(parent,12);TextView heading=text(label,12,GREEN);heading.setTypeface(null,1);parent.addView(heading);EditText e=new EditText(this);e.setText(value);e.setSingleLine(!multiline);fieldStyle(e);if(multiline){e.setMinLines(5);e.setGravity(Gravity.TOP);}parent.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 void metadata(String id,File file){metadataForm(id,file,null);}
 void editMetadata(JSONObject document){metadataForm(document.optString("id"),null,document);}
 void metadataForm(String id,File importedFile,JSONObject existing){
  hideKeyboard();boolean editing=existing!=null;LinearLayout form=column();form.setPadding(dp(22),dp(2),dp(22),dp(12));
  form.addView(text(editing?"จัดข้อมูลให้ค้นหาง่าย และกลับมาอ่านสะดวก":"เพิ่มความรู้ใหม่เข้าคลังส่วนตัวของคุณ",13,0xFF899681));
  EditText title=field(form,"ชื่อ Guideline *",editing?existing.optString("title"):"",false);title.setHint("เช่น Breast Cancer Guidelines");
  EditText org=field(form,"องค์กร / แหล่งที่มา",editing?existing.optString("org"):"",false);org.setHint("เช่น NCCN, สมาคมวิชาชีพ");
  EditText year=field(form,"ปีที่เผยแพร่",editing?existing.optString("year"):"",false);year.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);year.setHint("เช่น 2026 หรือ 2569");
  gap(form,12);TextView catLabel=text("หมวดหมู่โรค",12,GREEN);catLabel.setTypeface(null,1);form.addView(catLabel);String[] chosen={editing?existing.optString("category",CategoryCatalog.OTHER):CategoryCatalog.ALL.equals(filter)?CategoryCatalog.OTHER:filter};
  final Button[] category=new Button[1];category[0]=button(chosen[0]+"  ▾",()->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(category[0].getWindowToken(),0);chooseCategory(chosen[0],false,value->{chosen[0]=value;category[0].setText(value+"  ▾");});});category[0].setGravity(Gravity.START|Gravity.CENTER_VERTICAL);form.addView(category[0],new LinearLayout.LayoutParams(-1,dp(52)));gap(form,8);form.addView(text("ค้นหาหมวดหรือเพิ่มหมวดเฉพาะของคุณได้",11,0xFF93A08D));
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(form);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle(editing?"ข้อมูล Guideline":"เพิ่ม Guideline ใหม่").setView(scroll).setNegativeButton("ยกเลิก",(a,b)->{if(!editing)importedFile.delete();}).setPositiveButton("บันทึก",null).create();dialog.setOnCancelListener(a->{if(!editing)importedFile.delete();});
  dialog.setOnShowListener(a->{dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getButton(-1).setOnClickListener(v->{if(title.getText().toString().trim().isEmpty()){title.setError("กรุณาระบุชื่อ Guideline");return;}try{
   JSONObject changed=editing?new JSONObject(existing.toString()):new JSONObject().put("id",id).put("notes",new JSONObject());changed.put("title",title.getText().toString().trim()).put("org",org.getText().toString().trim()).put("year",year.getText().toString().trim()).put("category",chosen[0]);
   int position=editing?docs.indexOf(existing):0;if(editing)docs.set(position,changed);else docs.add(0,changed);
   if(persist()){hideKeyboard();dialog.dismiss();home();toast(editing?"บันทึกข้อมูลและหมวดหมู่แล้ว":"เพิ่ม Guideline เข้าคลังแล้ว");}else if(editing)docs.set(position,existing);else docs.remove(changed);
  }catch(Exception e){toast("บันทึกข้อมูลไม่สำเร็จ กรุณาลองใหม่");}});});dialog.show();
 }
 void open(JSONObject d,int initial){closePdf();try{descriptor=ParcelFileDescriptor.open(new File(getFilesDir(),d.optString("id")+".pdf"),ParcelFileDescriptor.MODE_READ_ONLY);renderer=new PdfRenderer(descriptor);active=d;page=Math.max(0,Math.min(initial,renderer.getPageCount()-1));base();LinearLayout top=row();top.addView(button("‹",this::home));TextView title=text(d.optString("title"),16,INK);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);LinearLayout tools=row();tools.addView(primary("✧ อธิบาย",()->study("explain")),new LinearLayout.LayoutParams(0,-2,1));tools.addView(button("สรุป Regimen",()->study("regimen")),new LinearLayout.LayoutParams(0,-2,1));root.addView(tools);ScrollView sc=new ScrollView(this);image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);sc.addView(image,new ScrollView.LayoutParams(-1,-2));root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout pages=row();prev=button("‹ ก่อนหน้า",()->{page--;renderPage();sc.scrollTo(0,0);});next=button("ถัดไป ›",()->{page++;renderPage();sc.scrollTo(0,0);});pageLabel=text("",12,INK);pageLabel.setGravity(Gravity.CENTER);pages.addView(prev);pages.addView(pageLabel,new LinearLayout.LayoutParams(0,-2,1));pages.addView(next);root.addView(pages);root.addView(button("เปิดด้วยแอป PDF อื่น / ขยายอ่าน",()->externalPdf()));root.addView(button("ลบเอกสาร",()->new AlertDialog.Builder(this).setTitle("ลบ PDF และสรุปทั้งหมด?").setMessage("การลบนี้ย้อนกลับไม่ได้").setNegativeButton("ยกเลิก",null).setPositiveButton("ลบ",(a,b)->{int pos=docs.indexOf(d);docs.remove(d);if(persist()){home();new File(getFilesDir(),d.optString("id")+".pdf").delete();}else docs.add(pos,d);}).show()));renderPage();}catch(Exception e){home();toast("เปิด PDF ไม่ได้ กรุณาลองเปิดด้วยแอปอื่น");}}
 void renderPage(){if(renderer==null)return;try(PdfRenderer.Page p=renderer.openPage(page)){int width=Math.min(1600,getResources().getDisplayMetrics().widthPixels*2);int height=Math.max(1,(int)((double)width*p.getHeight()/Math.max(1,p.getWidth())));if(height>7000){width=Math.max(1,width*7000/height);height=7000;}Bitmap nextBitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);nextBitmap.eraseColor(Color.WHITE);p.render(nextBitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(nextBitmap);if(bitmap!=null)bitmap.recycle();bitmap=nextBitmap;pageLabel.setText((page+1)+" / "+renderer.getPageCount());prev.setEnabled(page>0);next.setEnabled(page<renderer.getPageCount()-1);}catch(Exception|OutOfMemoryError e){toast("แสดงหน้านี้ไม่ได้ ลองเปิดด้วยแอป PDF อื่น");}}
 Uri pdfUri(){return Uri.parse("content://"+getPackageName()+".pdf/"+active.optString("id")+".pdf");}
 void externalPdf(){try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(pdfUri(),"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(ActivityNotFoundException e){toast("ยังไม่มีแอปเปิด PDF อื่นในเครื่อง");}}
 String prompt(String mode,String topic){return "ฉันเป็นนักศึกษาเภสัชศาสตร์ ใช้เฉพาะ PDF ที่แนบ: "+active.optString("title")+" ("+active.optString("year")+")\nหัวข้อ/หน้าที่สนใจ: "+topic+"\n"+(mode.equals("regimen")?"สรุป regimen เป็นตาราง: กลุ่มผู้ป่วย เงื่อนไข first-line ทางเลือก ขนาดยา วิธีให้ ความถี่ ระยะเวลา การปรับตามไต/ตับ ข้อห้าม monitoring":"อธิบายหลักการ เป้าหมายการรักษา เหตุผลการเลือกยา กลไก และประเด็นสำคัญให้เข้าใจง่าย")+"\nระบุหน้าอ้างอิงทุกข้อสำคัญ ไม่เติมขนาดยาหรือคำแนะนำที่เอกสารไม่ได้ระบุ หากข้อมูลขาดให้เขียนว่าไม่พบในเอกสาร หากไม่มีไฟล์แนบให้ขอ PDF ก่อนตอบ ใช้เพื่อการเรียน ไม่แทนการประเมินผู้ป่วยรายบุคคล";}
 void study(String mode){JSONObject notes=active.optJSONObject("notes");JSONObject n=notes==null?null:notes.optJSONObject(mode);LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),dp(12));form.addView(text("เตรียมคำถามและแนบ PDF ไปยังแอป AI\nแอปนี้ยังไม่ได้เรียก AI โดยตรง",12,Color.GRAY));EditText topic=field(form,"หัวข้อ / หน้าที่สนใจ",n==null?"หน้า "+(page+1):n.optString("topic"),false);form.addView(button("คัดลอกคำถาม",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Pharmnote prompt",prompt(mode,topic.getText().toString())));toast("คัดลอกแล้ว กรุณาแนบ PDF เมื่อถาม AI");}));form.addView(button("ส่งคำถามพร้อม PDF ไปแอป AI",()->{Intent i=new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,pdfUri()).putExtra(Intent.EXTRA_TEXT,prompt(mode,topic.getText().toString())).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newUri(getContentResolver(),"Guideline",pdfUri()));try{startActivity(Intent.createChooser(i,"เลือก ChatGPT หรือแอป AI ที่ติดตั้ง"));}catch(Exception e){toast("ไม่พบแอปที่รองรับ ใช้การคัดลอกคำถามและแนบ PDF เอง");}}));EditText answer=field(form,"คำตอบจาก AI / สรุปของคุณ",n==null?"":n.optString("answer"),true);EditText refs=field(form,"หน้า / ตารางอ้างอิง",n==null?"":n.optString("pages"),false);CheckBox checked=new CheckBox(this);checked.setText("ตรวจทานกับเอกสารต้นฉบับแล้ว");checked.setTextSize(12);checked.setChecked(n!=null&&n.optBoolean("reviewed"));form.addView(checked);form.addView(text("ตรวจสอบขนาดยา ข้อห้าม และบริบทผู้ป่วยก่อนใช้ทางคลินิก",11,Color.GRAY));ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(mode.equals("regimen")?"สรุป Regimen":"อธิบายเนื้อหา").setView(scroll).setNegativeButton("ปิด",null).setPositiveButton("บันทึก",null).create();final String originalAnswer=answer.getText().toString(),originalTopic=topic.getText().toString(),originalRefs=refs.getText().toString();final boolean originalChecked=checked.isChecked();Runnable dismiss=()->{boolean changed=!answer.getText().toString().equals(originalAnswer)||!topic.getText().toString().equals(originalTopic)||!refs.getText().toString().equals(originalRefs)||checked.isChecked()!=originalChecked;if(changed)new AlertDialog.Builder(this).setMessage("มีข้อความที่ยังไม่บันทึก ต้องการทิ้งการแก้ไข?").setNegativeButton("กลับไปแก้",null).setPositiveButton("ทิ้ง",(a,b)->dialog.dismiss()).show();else dialog.dismiss();};dialog.setCancelable(false);dialog.setOnKeyListener((di,key,event)->{if(key==KeyEvent.KEYCODE_BACK&&event.getAction()==KeyEvent.ACTION_UP){dismiss.run();return true;}return key==KeyEvent.KEYCODE_BACK;});dialog.setOnShowListener(di->{dialog.getButton(-2).setOnClickListener(v->dismiss.run());dialog.getButton(-1).setOnClickListener(v->{try{JSONObject oldNotes=active.optJSONObject("notes");JSONObject all=oldNotes==null?new JSONObject():new JSONObject(oldNotes.toString());all.put(mode,new JSONObject().put("topic",topic.getText()).put("answer",answer.getText()).put("pages",refs.getText()).put("reviewed",checked.isChecked()));active.put("notes",all);if(persist()){toast("บันทึกสรุปแล้ว");dialog.dismiss();}else active.put("notes",oldNotes);}catch(Exception e){toast("บันทึกไม่ได้");}});});dialog.show();}
 void exportBackup(){if(busy){toast("กรุณารอการนำเข้าเอกสาร");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"pharmnote-backup-"+System.currentTimeMillis()+".zip");startActivityForResult(i,2);}
 void writeBackup(Uri uri){JSONArray snapshot=new JSONArray();ArrayList<String> ids=new ArrayList<>();for(JSONObject d:docs){snapshot.put(d);ids.add(d.optString("id"));}busy=true;toast("กำลังส่งออกข้อมูล…");new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt");ZipOutputStream zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry("library.json"));zip.write(snapshot.toString(2).getBytes(StandardCharsets.UTF_8));zip.closeEntry();byte[] buf=new byte[8192];for(String id:ids){zip.putNextEntry(new ZipEntry(id+".pdf"));try(InputStream in=new FileInputStream(new File(getFilesDir(),id+".pdf"))){int n;while((n=in.read(buf))!=-1)zip.write(buf,0,n);}zip.closeEntry();}runOnUiThread(()->{busy=false;toast("ส่งออก PDF และสรุปครบแล้ว");});}catch(Exception e){runOnUiThread(()->{busy=false;toast("ส่งออกไม่สำเร็จ กรุณาลองใหม่");});}}).start();}
 void closePdf(){if(image!=null)image.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}if(renderer!=null){renderer.close();renderer=null;}if(descriptor!=null){try{descriptor.close();}catch(Exception ignored){}descriptor=null;}}
 @Override public void onBackPressed(){if(active!=null)home();else super.onBackPressed();}
 protected void onDestroy(){closePdf();super.onDestroy();}
